@layer hj.components {
  /* Customise: --hj-dialog-width · --hj-dialog-radius · --hj-dialog-padding · --hj-dialog-scrim */
  .hj-dialog-backdrop {
    position: fixed;
    inset: 0;
    z-index: var(--hj-z-overlay);
    min-height: 100dvh;
    background: var(--hj-scrim);
    opacity: var(--hj-dialog-scrim, 0.55);
    transition: opacity var(--hj-dur-base) var(--hj-ease-out);
  }
  .hj-dialog-backdrop[data-starting-style],
  .hj-dialog-backdrop[data-ending-style] {
    opacity: 0;
  }
  .hj-dialog-backdrop[data-ending-style] {
    transition-duration: var(--hj-dur-fast);
  }

  .hj-dialog-popup {
    --_w: var(--hj-dialog-width, 380px);
    position: fixed;
    inset: 0;
    z-index: var(--hj-z-overlay);
    margin: auto;
    width: min(var(--_w), calc(100vw - 32px));
    height: fit-content;
    max-height: calc(100dvh - 48px);
    overflow: auto;
    display: flex;
    flex-direction: column;
    gap: calc(8px * var(--hj-density));
    padding: var(--hj-dialog-padding, calc(24px * var(--hj-density)));
    border: 1px solid var(--hj-line);
    border-radius: var(--hj-dialog-radius, var(--hj-radius-lg));
    corner-shape: var(--hj-corner-shape, round);
    background: var(--hj-surface-2);
    color: var(--hj-fg);
    font-family: var(--hj-font-sans);
    outline: none;
    /* nested dialogs step back */
    transform: translateY(calc(-10px * var(--nested-dialogs, 0)))
      scale(calc(1 - 0.05 * var(--nested-dialogs, 0)));
    transition:
      transform var(--hj-dur-snappy-settle) var(--hj-ease-snappy-settle),
      opacity var(--hj-dur-base) var(--hj-ease-out);
  }
  .hj-dialog-popup[data-size='md'] {
    --_w: var(--hj-dialog-width, 480px);
  }
  .hj-dialog-popup[data-size='lg'] {
    --_w: var(--hj-dialog-width, 640px);
  }
  /* Arrive from .94 on a settled spring; leave faster, and never bounce. */
  .hj-dialog-popup[data-starting-style] {
    opacity: 0;
    transform: scale(0.94);
  }
  .hj-dialog-popup[data-ending-style] {
    opacity: 0;
    transform: scale(0.97);
    transition-duration: var(--hj-dur-fast);
    transition-timing-function: var(--hj-ease-out);
  }
  .hj-dialog-popup[data-nested-dialog-open]::after {
    content: '';
    position: absolute;
    inset: 0;
    border-radius: inherit;
    corner-shape: inherit;
    background: color-mix(in srgb, var(--hj-scrim) 18%, transparent);
    pointer-events: none;
  }

  .hj-dialog-title {
    margin: 0;
    padding-right: calc(36px * var(--hj-density));
    font: var(--hj-type-title);
    letter-spacing: var(--hj-tracking-title);
  }
  .hj-dialog-description {
    margin: 0;
    font-size: 14.5px;
    line-height: 1.55;
    color: var(--hj-fg-dim);
  }
  .hj-dialog-actions {
    display: flex;
    justify-content: flex-end;
    gap: calc(8px * var(--hj-density));
    margin-top: calc(16px * var(--hj-density));
  }

  .hj-dialog-close[data-icon] {
    position: absolute;
    top: 14px;
    right: 14px;
    display: grid;
    place-items: center;
    width: 32px;
    height: calc(32px * var(--hj-density-size));
    padding: 0;
    border: 0;
    border-radius: var(--hj-radius-pill);
    background: color-mix(in srgb, var(--hj-fg) 6%, transparent);
    color: var(--hj-fg-dim);
    font-size: 16px;
    line-height: 0;
    cursor: pointer;
    transition:
      background-color var(--hj-dur-fast) var(--hj-ease-out),
      color var(--hj-dur-fast) var(--hj-ease-out),
      transform var(--hj-dur-snappy) var(--hj-ease-snappy);
  }
  .hj-dialog-close[data-icon]::before {
    /* 44px hit area around a 32px drawing */
    content: '';
    position: absolute;
    inset: -6px;
  }
  .hj-dialog-close[data-icon]:hover {
    background: color-mix(in srgb, var(--hj-fg) 10%, transparent);
    color: var(--hj-fg);
  }
  .hj-dialog-close[data-icon]:active {
    transform: scale(0.92);
    transition-duration: 70ms;
  }
  .hj-dialog-close[data-icon] svg {
    width: 16px;
    height: 16px;
  }
}

'use client';
import { Dialog as Base } from '@base-ui/react/dialog';
import * as React from 'react';

import { useHanjiConfig } from '../../system/config.tsx';
import { elementPart, part } from '../../system/part.tsx';
import type { ElementPartProps, HanjiPart } from '../../system/part.tsx';
import { cls, flag, withDefaults } from '../../system/slot.ts';
import { ThemeScope } from '../../system/theme.tsx';

export const Root: typeof Base.Root = Base.Root;
export const Trigger: HanjiPart<typeof Base.Trigger> = part(
  Base.Trigger,
  'Dialog.Trigger',
  'hj-dialog-trigger',
);
export const Backdrop: HanjiPart<typeof Base.Backdrop> = part(
  Base.Backdrop,
  'Dialog.Backdrop',
  'hj-dialog-backdrop',
);
export const Title: HanjiPart<typeof Base.Title> = part(
  Base.Title,
  'Dialog.Title',
  'hj-dialog-title',
);
export const Description: HanjiPart<typeof Base.Description> = part(
  Base.Description,
  'Dialog.Description',
  'hj-dialog-description',
);
/** Footer row. Hold at most two actions; the safe one first, the consequence last. */
export const Actions: (props: ElementPartProps<'div'>) => React.ReactElement = elementPart(
  'div',
  'Dialog.Actions',
  'hj-dialog-actions',
);
export const createHandle: typeof Base.createHandle = Base.createHandle;

/** Portals to `<body>` but keeps the nearest `<Theme>`'s paper, accent and density. */
export function Portal({ children, ...props }: Base.Portal.Props): React.ReactElement {
  return (
    <Base.Portal {...props}>
      <ThemeScope>{children}</ThemeScope>
    </Base.Portal>
  );
}

export interface PopupOwnProps {
  /** Width: sm 380 (hanji), md 480, lg 640. */
  size?: 'sm' | 'md' | 'lg';
}
export interface PopupProps extends PopupOwnProps, Base.Popup.Props {}

/** The dialog surface: surface-2 on a black scrim, enters from scale .94 on a settled spring. */
export function Popup(props: PopupProps): React.ReactElement {
  const config = useHanjiConfig();
  const { size = 'sm', className, ...rest } = withDefaults(config, 'Dialog.Popup', props);
  return (
    <Base.Popup
      {...rest}
      data-size={size}
      className={cls(config, 'Dialog.Popup', 'hj-dialog-popup', className)}
    />
  );
}

export interface CloseOwnProps {
  /** Render the corner ✕ icon button. Defaults to true when the Close has no children. */
  icon?: boolean;
}
export interface CloseProps extends CloseOwnProps, Base.Close.Props {}

/** Closes the dialog. With no children it renders the corner ✕ with an accessible label. */
export function Close(props: CloseProps): React.ReactElement {
  const config = useHanjiConfig();
  const { icon, className, children, ...rest } = withDefaults(config, 'Dialog.Close', props);
  const asIcon = icon ?? children === undefined;
  return (
    <Base.Close
      aria-label={asIcon ? config.strings.close : undefined}
      {...rest}
      data-icon={flag(asIcon)}
      className={cls(config, 'Dialog.Close', 'hj-dialog-close', className)}
    >
      {asIcon ? config.icons.x : children}
    </Base.Close>
  );
}

export interface ContentProps extends PopupProps {
  /** Draw the scrim. @default true */
  backdrop?: boolean;
  /** Where to portal. Defaults to `<body>`. */
  container?: Base.Portal.Props['container'];
  keepMounted?: boolean;
}

/** Shorthand for Portal + Backdrop + Popup — the common case in one part. */
export function Content({
  backdrop = true,
  container,
  keepMounted,
  ...popup
}: ContentProps): React.ReactElement {
  return (
    <Portal container={container} keepMounted={keepMounted}>
      {backdrop ? <Backdrop /> : null}
      <Popup {...popup} />
    </Portal>
  );
}

export * as Dialog from './dialog.tsx';
export type {
  CloseOwnProps as DialogCloseOwnProps,
  CloseProps as DialogCloseProps,
  ContentProps as DialogContentProps,
  PopupOwnProps as DialogPopupOwnProps,
  PopupProps as DialogPopupProps,
} from './dialog.tsx';
